// Check-in de saída abre um trajeto; check-in na unidade fecha. Até 3 trajetos por dia.
const b = $json.body || {};
const janelas = ['ida', 'retorno_almoco', 'segundo_local'];
if (!b.medico_id || !['saida', 'chegada'].includes(b.evento)) throw new Error('payload inválido');
if (b.evento === 'saida' && !janelas.includes(b.janela)) throw new Error('janela deve ser ida, retorno_almoco ou segundo_local');
return { json: { medico_id: String(b.medico_id), evento: b.evento, janela: b.janela || null,
  unidade: b.unidade || null, correlation_id: b.correlation_id || ('MED-' + b.medico_id + '-' + Date.now().toString(36)) } };

// Decide se vale chamar o Google Routes agora (economia de chamadas).
const t = $json;                                   // trajeto aberto + posição do Redis
const gps = t.gps ? JSON.parse(t.gps) : null;      // {lat, lng, em}
const agora = Date.now();
const semSinalMin = gps ? (agora - new Date(gps.em)) / 60000 : 999;
const rad = x => x * Math.PI / 180;
const distM = (a, b) => {                           // distância aproximada em metros (haversine)
  if (!a || !b || a.lat == null || b.lat == null) return Infinity;
  const R = 6371000, dLat = rad(b.lat - a.lat), dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};
const ultimo = { lat: t.ultimo_calc_lat, lng: t.ultimo_calc_lng };
const parado = gps && distM(gps, ultimo) < 200;     // não andou 200 m desde o último cálculo
const folgaAnterior = t.folga_min == null ? 0 : t.folga_min;
return { json: {
  ...t, gps,
  sem_sinal_min: Math.round(semSinalMin),
  chamar_google: !!gps && semSinalMin < 10 && !parado,
  // acima de 30 min de folga não precisa de trânsito em tempo real (SKU Essentials, metade do preço)
  routing: folgaAnterior > 30 ? 'TRAFFIC_UNAWARE' : 'TRAFFIC_AWARE',
  correlation_id: t.correlation_id || ('MED-' + t.medico_id + '-' + t.trajeto_id)
} };

// Junta o resultado do Google (ou o ETA anterior) e calcula folga, estado e próxima checagem.
const base = $('Decidir chamada').item.json;
const rota = ($json.routes || [])[0];
const etaMin = rota ? Math.ceil(parseInt(String(rota.duration).replace('s', ''), 10) / 60) : (base.eta_min ?? null);
const minAte1a = (new Date(base.primeira_consulta_em) - Date.now()) / 60000;
const MARGEM = 15;                                         // margem de segurança
const folga = etaMin == null ? null : Math.round(minAte1a - etaMin - MARGEM);
let estado = 'no_horario';
if (base.sem_sinal_min >= 10) estado = 'incidente';
else if (folga != null && folga < 0) estado = 'atraso';
// intervalo adaptativo: 1 min com folga menor que 15 min, senão 5 min
const proxMin = folga != null && folga < 15 ? 1 : 5;
return { json: {
  correlation_id: base.correlation_id, trajeto_id: base.trajeto_id, medico_id: base.medico_id,
  especialidade: base.especialidade, unidade: base.unidade, janela: base.janela,
  eta_min: etaMin, folga_min: folga, atraso_previsto_min: folga != null && folga < 0 ? -folga : 0,
  estado, estado_anterior: base.estado || 'no_horario', mudou: estado !== (base.estado || 'no_horario'),
  chamou_google: !!rota, routing: base.routing, proxima_checagem_min: proxMin,
  lat: base.gps ? base.gps.lat : null, lng: base.gps ? base.gps.lng : null
} };
